INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q929265', 'Battle of Naissus', 'The Battle of Naissus in 268 or 269 was the defeat of a Gothic coalition by the Roman Empire under Emperor Gallienus (or Emperor Claudius II Gothicus) and the future Emperor Aurelian near Naissus (Niš). The events around the invasion and the battle are an important part of the history of the Crisis of the Third Century.', 268, 9, NULL, NULL, NULL, NULL, 'month', 'September 268', 64, 'https://en.wikipedia.org/wiki/Battle_of_Naissus'),
  ('Q7510408', 'Siege of Sirmium', 'The siege of Sirmium in 580–582 was a decisive event in the history of the Balkans. The fall of the city to the Avars deprived the Byzantine Empire of its major stronghold on the northwestern Danube, opening the path for devastating incursions by the Avars and their Slavic allies into the Balkans.', 580, 5, NULL, 582, NULL, NULL, 'month', 'May 580 – 582', 45, 'https://en.wikipedia.org/wiki/Siege_of_Sirmium'),
  ('Q1504536', 'Battles of Viminacium', 'The Battles of Viminacium were a series of three battles fought against the Avars by the Eastern Roman Empire. They were decisive Roman successes, which were followed by an invasion of Pannonia.', 599, NULL, NULL, NULL, NULL, NULL, 'year', '599', 43, 'https://en.wikipedia.org/wiki/Battles_of_Viminacium'),
  ('Q194951', 'Battle of Haram', 'The Battle of Haram or Chramon (modern Banatska Palanka) was fought between the forces of King Stephen II (r. 1116–1131) of Hungary and Emperor John II Komnenos (r.', 1128, NULL, NULL, NULL, NULL, NULL, 'year', '1128', 37, 'https://en.wikipedia.org/wiki/Battle_of_Haram'),
  ('Q172368', 'Battle of Sirmium', 'The Battle of Sirmium, Battle of Semlin or Battle of Zemun (Hungarian: zimonyi csata) was fought on July 8, 1167 between the Byzantine Empire, and the Kingdom of Hungary. The Byzantines achieved a decisive victory, forcing the Hungarians to sue for peace on Byzantine terms.', 1167, 7, 8, NULL, NULL, NULL, 'day', '8 July 1167', 56, 'https://en.wikipedia.org/wiki/Battle_of_Sirmium'),
  ('Q4871982', 'Battle of Pantina', 'The Battle of Pantina was fought between the Byzantine Empire and the Grand Principality of Serbia in 1167. It was part of a war of succession within Serbia, in which the Byzantines intervened on behalf of the deposed Grand Prince Tihomir of Serbia against his rebellious younger brother, Prince Nemanja, who emerged victorious and was crowned afterwards.', 1167, NULL, NULL, NULL, NULL, NULL, 'year', '1167', 37, 'https://en.wikipedia.org/wiki/Battle_of_Pantina'),
  ('Q612288', 'Battle of Pločnik', 'The Battle of Pločnik was fought sometime between 1385 and 1387 near the village of Pločnik (near Prokuplje in today''s southeastern Serbia), between the forces of Serbian Prince Lazar Hrebeljanović, and the invading Ottoman Army of Sultan Murad I.', 1385, NULL, NULL, NULL, NULL, NULL, 'year', '1385', 56, 'https://en.wikipedia.org/wiki/Battle_of_Plo%C4%8Dnik'),
  ('Q3395349', 'Battle of Tripolje', 'The Battle of Tripolje (Serbian Cyrillic: битка код Трипоља/бој на Трипољу), also known as the Battle of Gračanica (Грачаничка битка), was fought in November 1402 between the Serbian Despotate, ruled by the Lazarević dynasty, and the Branković family, aided by the Ottoman Empire. Following the Ottoman defeat at Ankara in 1402, Serbian ruler Stefan Lazarević saw an opportunity to free himself of Ottoman overlordship.', 1402, 11, 21, NULL, NULL, NULL, 'day', '21 November 1402', 39, 'https://en.wikipedia.org/wiki/Battle_of_Tripolje'),
  ('Q1007513', 'Siege of Golubac', 'The siege of Golubac (Hungarian: Galambóc) was a military conflict between the Hungarian–Wallachian–Lithuanian alliance and the Ottoman Empire in May 1428. This siege was the first battle in Hungarian military history in which the Hungarian army used significant artillery.', 1428, 5, NULL, NULL, NULL, NULL, 'month', 'May 1428', 41, 'https://en.wikipedia.org/wiki/Siege_of_Golubac'),
  ('Q12756567', 'Siege of Belgrade', 'The siege of Belgrade was a long siege by the forces of the Ottoman Empire, lasted about six or seven months in 1440. Belgrade was an important fortified town of the Serbian Despotate and the key fortress of the Hungarian defense line after the Ottoman subjugation of Serbia in 1439.', 1440, 4, NULL, 1440, 10, NULL, 'month', 'April 1440 – October 1440', 45, 'https://en.wikipedia.org/wiki/Siege_of_Belgrade_(1440)'),
  ('Q3339470', 'Battle of Niš', 'The Battle of Nish (early November 1443) was fought between the Crusaders led by John Hunyadi and Đurađ Branković and the Ottoman Empire led by Kasım Pasha. It saw the Crusaders capture the Ottoman stronghold of Nish (Niš) in Serbia, and defeat two armies of the Ottoman Empire.', 1443, 11, NULL, NULL, NULL, NULL, 'month', 'November 1443', 52, 'https://en.wikipedia.org/wiki/Battle_of_Nish_(1443)'),
  ('Q698706', 'Battle of Kosovo', 'The Second Battle of Kosovo (Hungarian: második rigómezei csata, Turkish: İkinci Kosova Muharebesi) was a land battle between a Hungarian-led Crusader army and the Ottoman Empire at Kosovo field (the Field of Blackbirds) that took place from 17–20 October 1448. It was the culmination of a Hungarian offensive to avenge the defeat at the Battle of Varna four years earlier.', 1448, 10, 17, 1448, 10, 20, 'day', '17 October 1448 – 20 October 1448', 68, 'https://en.wikipedia.org/wiki/Battle_of_Kosovo_(1448)'),
  ('Q3395325', 'Battle of Kruševac', 'The Battle of Kruševac was fought on October 2, 1454 between the forces of the Serbian Despotate, allied with the Kingdom of Hungary, and the Ottoman Empire. In 1454 the Ottomans launched a major invasion against Serbia, at the helm of which was the Sultan himself, Mehmed the Conqueror.', 1454, 10, 2, NULL, NULL, NULL, 'day', '2 October 1454', 37, 'https://en.wikipedia.org/wiki/Battle_of_Kru%C5%A1evac'),
  ('Q244980', 'Siege of Belgrade', 'The siege of Belgrade, or the siege of Nándorfehérvár (Hungarian: Nándorfehérvár ostroma or nándorfehérvári diadal, lit. "Triumph of Nándorfehérvár"; Serbian Cyrillic: Опсада Београда, romanized: Opsada Beograda) was a military blockade of Belgrade that occurred 4–22 July 1456 in the aftermath of the fall of Constantinople in 1453 marking the Ottomans'' attempts to expand further into Europe.', 1456, 7, 4, 1456, 7, 22, 'day', '4 July 1456 – 22 July 1456', 72, 'https://en.wikipedia.org/wiki/Siege_of_Belgrade_(1456)'),
  ('Q535542', 'Siege of Belgrade', 'The siege of Belgrade (Hungarian: Nándorfehérvár ostroma) in 1521 is an event that followed as a result of the third major Ottoman attack on this Hungarian stronghold in the Ottoman–Hungarian wars at the time of the greatest expansion of the Ottoman Empire to the west. Ottoman Sultan Suleiman the Magnificent launched his army in mid-May 1521.', 1521, 6, 25, 1521, 8, 29, 'day', '25 June 1521 – 29 August 1521', 64, 'https://en.wikipedia.org/wiki/Siege_of_Belgrade_(1521)'),
  ('Q1293343', 'Siege of Šabac', 'The siege of Šabac or Szabács occurred on 7 July in the year 1521 when the Ottoman Empire conquered the Šabac fortress. In 1520 Suleiman the Magnificent ascended to the throne.', 1521, 6, 20, 1521, 7, 7, 'day', '20 June 1521 – 7 July 1521', 37, 'https://en.wikipedia.org/wiki/Siege_of_%C5%A0abac_(1521)'),
  ('Q699902', 'Siege of Belgrade', 'The siege of Belgrade was a successful attempt by Habsburg troops under the command of the Elector of Bavaria Maximilian II Emanuel to capture the city of Belgrade from the Ottoman Empire. Part of the Great Turkish War (1683–1699), the siege lasted a month and culminated in the capture of the city on 6 September 1688.', 1688, 7, 30, 1688, 9, 6, 'day', '30 July 1688 – 6 September 1688', 53, 'https://en.wikipedia.org/wiki/Siege_of_Belgrade_(1688)'),
  ('Q4438396', 'Battle of Batočina', 'The Battle of Batočina (Serbian: Битка код Баточине) was fought on 29–30 August 1689 near the town of Batočina in the Sanjak of Smederevo (now in central Serbia), between forces of the Holy Roman Empire and the Ottoman Empire during the Great Turkish War (1683–1699). The Serbian Militia under the command of Pavle Nestorović as a vanguard unit of the Habsburg army was victorious against a vanguard unit of the Ottoman army during the battle.', 1689, 8, 29, 1689, 8, 30, 'day', '29 August 1689 – 30 August 1689', 37, 'https://en.wikipedia.org/wiki/Battle_of_Bato%C4%8Dina'),
  ('Q4438417', 'Battle of Niš', 'The Battle of Niš was fought on 24 September 1689, near the city of Niš in southern Serbia, between the Ottoman Empire and the Holy Roman Empire as part of the Great Turkish War. The Austrian commander, Louis William, Margrave of Baden-Baden, defeated the Ottomans and captured the city.', 1689, 9, 24, NULL, NULL, NULL, 'day', '24 September 1689', 43, 'https://en.wikipedia.org/wiki/Battle_of_Ni%C5%A1_(1689)'),
  ('Q7509869', 'Siege of Belgrade', 'The siege of Belgrade in 1690 was the fifth siege of that city, taking place during the Great Turkish War. Belgrade had been conquered by the Austrians under the elector of Bavaria, Maximilian II Emanuel, on September 6, 1688, after a five-week siege.', 1690, 10, 2, 1690, 10, 8, 'day', '2 October 1690 – 8 October 1690', 47, 'https://en.wikipedia.org/wiki/Siege_of_Belgrade_(1690)'),
  ('Q690481', 'Battle of Slankamen', 'The Battle of Slankamen was fought on 19 August 1691, near Slankamen in the Ottoman Sanjak of Syrmia (modern-day Vojvodina, Serbia), between the Ottoman Empire, and Habsburg Austrian forces during the Great Turkish War. The battle saw a Turkish-Transylvanian force led by Emeric Thököly and Mustafa Köprülü suffer an overwhelming defeat by an Imperial army commanded by Ludwig Wilhelm of Baden.', 1691, 8, 19, NULL, NULL, NULL, 'day', '19 August 1691', 61, 'https://en.wikipedia.org/wiki/Battle_of_Slankamen'),
  ('Q2237649', 'Battle of Ulaş', 'The Battle of Olasch (also Ólas, Ulaş, Olaschin) took place after a Habsburg Imperial army led by Saxon Elector General, Augustus II the Strong, laid siege to Turkish held Temesvár. On 26 August 1696, after learning that Sultan Mustafa II''s relief army was crossing the Danube at Pancsova, Augustus gave up the siege and headed to meet the Ottoman army.', 1696, 8, 26, NULL, NULL, NULL, 'day', '26 August 1696', 48, 'https://en.wikipedia.org/wiki/Battle_of_Olasch'),
  ('Q517486', 'Battle of Zenta', 'The Battle of Zenta, also known as the Battle of Senta, took place on 11 September 1697 near Zenta, in the Kingdom of Hungary, then under Ottoman occupation (present-day Serbia). It was a decisive engagement of the Great Turkish War, fought between the forces of the Ottoman Empire and the Holy League.', 1697, 9, 11, NULL, NULL, NULL, 'day', '11 September 1697', 68, 'https://en.wikipedia.org/wiki/Battle_of_Zenta'),
  ('Q690391', 'Battle of Petrovaradin', 'The Battle of Petrovaradin also known as the Battle of Peterwardein, took place on 5 August 1716 during the Austro-Turkish War when the Ottoman army besieged the Habsburg-controlled fortress of Petrovaradin on the Military Frontier of the Habsburg monarchy (today Novi Sad, Vojvodina, Serbia). The Ottomans attempted to capture Petrovaradin, the so-called Gibraltar on the Danube, but experienced a great defeat by an army half the size of their own, similar to the defeat they had experienced in 1697 at the Battle of Zenta.', 1716, 8, 5, NULL, NULL, NULL, 'day', '5 August 1716', 62, 'https://en.wikipedia.org/wiki/Battle_of_Petrovaradin'),
  ('Q26799687', 'Austro-Turkish War of 1716–1718', 'The Austro-Turkish War (1716–1718) was fought between the Habsburg monarchy and the Ottoman Empire. The 1699 Treaty of Karlowitz was not an acceptable permanent agreement for the Ottoman Empire.', 1716, 1, NULL, 1718, 7, 21, 'month', 'January 1716 – 21 July 1718', 63, 'https://en.wikipedia.org/wiki/Austro-Turkish_War_(1716%E2%80%931718)'),
  ('Q2631076', 'Siege of Belgrade', 'The siege of Belgrade was the capture by the Habsburg forces under the command of Prince Eugene of Savoy of the strategically-important city of Belgrade from the Ottoman Empire. It took place during the Austro-Turkish War (1716–1718), barely a year after the Habsburg victory at the Battle of Petrovaradin (Peterwardein).', 1717, 6, 18, 1717, 8, 21, 'day', '18 June 1717 – 21 August 1717', 56, 'https://en.wikipedia.org/wiki/Siege_of_Belgrade_(1717)'),
  ('Q5036987', 'Capture of Belgrade', 'The Siege of Belgrade saw the recapture of Belgrade (بلغراد:Ottoman Turkish/capital of modern Serbia) by the Ottoman Empire in 1739.', 1739, 7, NULL, 1739, 9, 18, 'month', 'July 1739 – 18 September 1739', 39, 'https://en.wikipedia.org/wiki/Siege_of_Belgrade_(1739)'),
  ('Q11821309', 'Treaty of Belgrade', 'The Treaty of Belgrade, also known as the Belgrade Peace, was a peace treaty between the Habsburg Monarchy and Ottoman Empire, that was signed on September 18, 1739, in Belgrade (modern Serbia), thus ending the Austro-Turkish War (1737–1739). Agreed territorial changes were substantial, and also favorable for the Ottoman side, since Habsburgs had to cede three regions: the Banat of Craiova (modern Oltenia), the Kingdom of Serbia with Belgrade, and Bosnian section of Posavina, thus placing the newly defined Habsburg-Ottoman border on the rivers Sava and Danube.', 1739, 9, 18, NULL, NULL, NULL, 'day', '18 September 1739', 67, 'https://en.wikipedia.org/wiki/Treaty_of_Belgrade'),
  ('Q7509870', 'Siege of Belgrade', 'In the siege of Belgrade (15 September – 8 October 1789) a Habsburg Austrian army led by feldmarschall Ernst Gideon von Laudon besieged an Ottoman force under Osman Pasha in the fortress of Belgrade. After a three-week leaguer, the Austrians forced the surrender of the fortress.', 1789, 9, 15, 1789, 10, 8, 'day', '15 September 1789 – 8 October 1789', 48, 'https://en.wikipedia.org/wiki/Siege_of_Belgrade_(1789)'),
  ('Q692074', 'Battle of Ivankovac', 'The Battle of Ivankovac (Serbian: Бој на Иванковцу, romanized: Boj na Ivankovcu) was the first full-scale confrontation between Serbian revolutionaries and the regular forces of the Ottoman Empire during the First Serbian Uprising. In the summer of 1805, Hafiz Mustafa Agha, known in historiography as "Hafiz Pasha", gathered an army in the Sanjak of Niš to crush the Serbian rebels led by Milenko Stojković near the village of Ivankovac.', 1805, 8, 18, NULL, NULL, NULL, 'day', '18 August 1805', 45, 'https://en.wikipedia.org/wiki/Battle_of_Ivankovac'),
  ('Q2750389', 'Battle of Mišar', 'The Battle of Mišar (Serbian: Бој на Мишару, romanized: Boj na Mišaru) was fought between Serbian revolutionaries and an Ottoman army, it took place from 13 to 15 August 1806 during the First Serbian Uprising. After repulsing an Ottoman force at Ivankovac, the year before, the Serbian insurgents under Karađorđe took strong position, entrenched in sconces on the field of Mišar Hill, near Šabac west of Belgrade.', 1806, 8, 12, 1806, 8, 15, 'day', '12 August 1806 – 15 August 1806', 50, 'https://en.wikipedia.org/wiki/Battle_of_Mi%C5%A1ar'),
  ('Q12756563', 'Siege of Belgrade', 'The Siege of Belgrade (Serbian: Опсада Београда, romanized: Opsada Beograda), known as the Liberation of Belgrade (Ослобођење Београда, Oslobođenje Beograda) was carried out by the Serbian rebels led by Karađorđe, seeking to overthrow the Ottoman government in the Sanjak of Smederevo, which was seated in the Belgrade Fortress. Following the victories at Mišar (13–15 August) and Deligrad (3 September), the Serbian rebels marched towards Belgrade.', 1806, 12, 12, 1806, 12, 26, 'day', '12 December 1806 – 26 December 1806', 41, 'https://en.wikipedia.org/wiki/Siege_of_Belgrade_(1806)'),
  ('Q1551047', 'Battle of Čegar', 'The Battle of Čegar (Serbian: Битка на Чегру/Bitka na Čegru), also known as the Battle of Kamenica (Бој на Каменици/Boj na Kamenici) took place during the First Serbian Uprising between the Serbian Revolutionaries and Ottoman forces near the Niš Fortress on 31 May 1809. Fought on the Čegar hill situated between the villages of Donji Matejevac and Kamenica near Niš in what is today southeastern Serbia, it ended in an Ottoman victory.', 1809, 4, 15, 1809, 5, 31, 'day', '15 April 1809 – 31 May 1809', 45, 'https://en.wikipedia.org/wiki/Battle_of_%C4%8Cegar'),
  ('Q368689', 'First Serbian Uprising', 'The First Serbian Uprising was an uprising of Serbs in Orašac against the Dahije, and later the Ottoman Empire from 14 February 1804 to 7 October 1813. The uprising began as a local revolt against renegade janissary officers who had seized power in a coup d''état against the Ottoman sultan.', 1813, 10, 7, 1813, 10, 7, 'day', '7 October 1813', 69, 'https://en.wikipedia.org/wiki/First_Serbian_Uprising'),
  ('Q5638135', 'Hadži-Prodan''s rebellion', 'Hadži-Prodan''s rebellion (Serbian: Хаџи-Проданова буна/Hadži-Prodanova buna) was a Serbian rebellion against the Ottoman Empire, which took place from 27 September to 30 December 1814. It occurred between the First (1804–13) and Second (1815) uprisings of the Serbian Revolution.', 1814, 9, 27, 1814, 12, 30, 'day', '27 September 1814 – 30 December 1814', 39, 'https://en.wikipedia.org/wiki/Had%C5%BEi-Prodan''s_rebellion'),
  ('Q243585', 'Second Serbian Uprising', 'The Second Serbian Uprising was the second phase of the Serbian Revolution against the Ottoman Empire, which erupted shortly after the re-annexation of the country to the Ottoman Empire in 1813. The occupation was enforced following the defeat of the First Serbian Uprising (1804–1813), during which Serbia existed as a de facto independent state for over a decade.', 1815, 4, 23, 1817, 7, 26, 'day', '23 April 1815 – 26 July 1817', 67, 'https://en.wikipedia.org/wiki/Second_Serbian_Uprising'),
  ('Q14833923', 'Takovo Meeting', 'The Takovo Meeting (Serbian: Састанак у Такову, romanized: Sastanak u Takovu) was the gathering of Serbian leaders held on 23 April [O.S. 11 April] 1815 (Palm Sunday) at Takovo, a village near present-day Gornji Milanovac. Two years following the collapse of the First Serbian Uprising, the decision was made to start a new uprising against the Ottoman Empire under the leadership of Miloš Obrenović.', 1815, 4, 24, NULL, NULL, NULL, 'day', '24 April 1815', 37, 'https://en.wikipedia.org/wiki/Takovo_Meeting'),
  ('Q686564', 'First Serbian–Ottoman War', 'The First Serbian–Ottoman War (Serbian: Први српско-турски рат, romanized: Prvi srpsko-turski rat), was a military conflict fought by the Principality of Serbia against the Ottoman Empire. Serbia declared war on the Ottoman Empire on 30 June 1876, during the Herzegovina Uprising.', 1876, 6, 30, 1878, 3, 3, 'day', '30 June 1876 – 3 March 1878', 52, 'https://en.wikipedia.org/wiki/First_Serbian%E2%80%93Ottoman_War'),
  ('Q3658001', 'Battle of Pirot', 'The Battle of Pirot (Bulgarian: Битка при Пирот Serbian: Битка код Пирота) took place between 26 and 27 November 1885,[a] during the Serbo-Bulgarian War, near the town of Pirot, Serbia. The battle opposed the Bulgaria Western Corps to the Serbian Nišava Army.', 1885, 11, 27, NULL, NULL, NULL, 'day', '27 November 1885', 50, 'https://en.wikipedia.org/wiki/Battle_of_Pirot'),
  ('Q1300440', 'Treaty of Bucharest', 'The Treaty of Bucharest was signed by Serbia and Bulgaria on 3 March [O.S. 19 February] 1886 in Bucharest, the capital of Romania, and marked the end of the Serbo-Bulgarian War. The treaty contained a single article, stating that peace between the two countries was restored.', 1886, 3, 3, NULL, NULL, NULL, 'day', '3 March 1886', 57, 'https://en.wikipedia.org/wiki/Treaty_of_Bucharest_(1886)'),
  ('Q682699', 'Battle of Kolubara', 'The Battle of Kolubara (Serbian Cyrillic: Колубарска битка, German: Schlacht an der Kolubara) was fought between Austria-Hungary and Serbia in November and December 1914, during the Serbian Campaign of 1914. It commenced on 16 November, when the Austro-Hungarians under the command of Oskar Potiorek reached the Kolubara river during their third invasion of Serbia that year, having captured the strategic town of Valjevo and forced the Serbian army to undertake a series of retreats.', 1914, 11, 16, 1914, 12, 15, 'day', '16 November 1914 – 15 December 1914', 64, 'https://en.wikipedia.org/wiki/Battle_of_Kolubara'),
  ('Q697748', 'Battle of Cer', 'The Battle of Cer was a military campaign fought between Austria-Hungary and Serbia in August 1914, starting three weeks into the Serbian Campaign of 1914, the initial military action of the First World War. It took place around Cer Mountain and several surrounding villages, as well as the town of Šabac.', 1914, 8, 15, 1914, 8, 24, 'day', '15 August 1914 – 24 August 1914', 64, 'https://en.wikipedia.org/wiki/Battle_of_Cer'),
  ('Q2457677', 'Morava Offensive', 'The Morava Offensive Operation (Bulgarian: Моравска настъпателна операция), (Serbian: Битка на Морави) was undertaken by the Bulgarian First Army between 14 October 1915 and 9 November 1915, as part of the strategic offensive operation of Army Group Mackensen against Serbia in 1915. Under the command of Lieutenant General Kliment Boyadzhiev, the Bulgarians seized the fortified areas of Pirot, Niš and the valley of the river Morava.', 1915, 11, 9, 1915, 11, 9, 'day', '9 November 1915', 51, 'https://en.wikipedia.org/wiki/Morava_Offensive'),
  ('Q15253897', '1918 protest in Zagreb', 'On 5 December 1918, four days after the proclamation of the Kingdom of Serbs, Croats and Slovenes, the National Guards (an armed force of the National Council of the State of Slovenes, Croats and Serbs) and Sokol volunteers suppressed a protest and engaged in an armed clash against the soldiers of the 25th Regiment of the Royal Croatian Home Guard and the 53rd Regiment of the former Austro-Hungarian Common Army. National Guardsmen stopped the soldiers at the Ban Jelačić Square in Zagreb.', 1918, 12, 5, NULL, NULL, NULL, 'day', '5 December 1918', 41, 'https://en.wikipedia.org/wiki/1918_protest_in_Zagreb'),
  ('Q472100', 'Bombing of Belgrade in 1941', 'Operation Retribution (German: Unternehmen Strafgericht) or Operation Punishment was the April 1941 German bombing of Belgrade, the capital of Yugoslavia, in retaliation for the coup d''état that overthrew the government that had signed the Tripartite Pact. The bombing occurred in the first days of the German-led Axis invasion of Yugoslavia during World War II. The Royal Yugoslav Army Air Force (VVKJ) had only 77 modern fighter aircraft available to defend Belgrade against the hundreds of German fighters and bombers that struck in the first wave early on 6 April.', 1941, 4, 6, NULL, NULL, NULL, 'day', '6 April 1941', 61, 'https://en.wikipedia.org/wiki/German_bombing_of_Belgrade'),
  ('Q1563435', 'Battle of Loznica', 'The Battle of Loznica involved an attack on the German garrison of that town by the Jadar Chetnik Detachment on 31 August 1941. Following the World War II German-led Axis invasion of Yugoslavia in April 1941, the Kingdom of Yugoslavia was partitioned.', 1941, 8, 31, NULL, NULL, NULL, 'day', '31 August 1941', 37, 'https://en.wikipedia.org/wiki/Battle_of_Loznica_(1941)'),
  ('Q287151', 'communist purges in Serbia in 1944–1945', 'The communist purges in Serbia in 1944–1945 are war crimes that were committed by members of the Yugoslav Partisan Movement and the post-war communist authorities after they gained control over Serbia, against people perceived as war criminals, quislings and ideological opponents. Most of these purges were committed between October 1944 and May 1945.', 1944, NULL, NULL, 1945, NULL, NULL, 'year', '1944–1945', 41, 'https://en.wikipedia.org/wiki/Communist_purges_in_Serbia_in_1944%E2%80%931945'),
  ('Q328357', 'Belgrade offensive', 'The Belgrade offensive or the Belgrade strategic offensive operation (Serbo-Croatian: Beogradska operacija / Београдска операција; Russian: Белградская стратегическая наступательная операция, Belgradskaya strategicheskaya nastupatel''naya operatsiya) (15 September – 24 November 1944) was a military operation during World War II in Yugoslavia in which Belgrade was liberated from the German Wehrmacht through the joint efforts of the Soviet Red Army, Yugoslav Partisans, and the Bulgarian Army. Soviet forces and local militias launched separate but loosely cooperative operations that undermined…', 1944, 11, 24, 1944, 11, 24, 'day', '24 November 1944', 67, 'https://en.wikipedia.org/wiki/Belgrade_offensive'),
  ('Q2338734', 'Battle of Batina', 'The Battle of Batina or Batina Operation (Serbo-Croatian: Bitka kod Batine) was fought on the Syrmian Front of the Second World War between the units of the Red Army and the Yugoslav Partisans against the Wehrmacht and their allies. The battle took place from 11 to 29 November 1944 near the village of Batina in Baranja, on the right bank of the Danube River.', 1944, 11, 29, 1944, 11, 19, 'day', '29 November 1944 – 19 November 1944', 41, 'https://en.wikipedia.org/wiki/Battle_of_Batina'),
  ('Q1030724', 'Insurgency in the Preševo Valley', 'The insurgency in the Preševo Valley was an approximately two year-long armed conflict between 12 June 1999 until 1 June 2001, between the Federal Republic of Yugoslavia and the ethnic Albanian separatists of the Liberation Army of Preševo, Medveđa and Bujanovac (UÇPMB). There were instances during the conflict in which the Yugoslav government requested Kosovo Force (KFOR) support in suppressing UÇPMB attacks since they could only use lightly armed military forces as part of the Kumanovo Treaty that ended the Kosovo War, which created a buffer zone between FR Yugoslavia and Kosovo.', 1999, 6, 12, 2001, 6, 1, 'day', '12 June 1999 – 1 June 2001', 61, 'https://en.wikipedia.org/wiki/Insurgency_in_the_Pre%C5%A1evo_Valley'),
  ('Q282140', '2010 Serbia earthquake', 'An earthquake of magnitude 5.5 and a maximum Mercalli intensity of VI (Strong) occurred on 3 November 2010 in central Serbia just several kilometers from the city of Kraljevo. The shock was felt across the country, including the capital Belgrade, and in neighboring countries.', 2010, 11, 3, NULL, NULL, NULL, 'day', '3 November 2010', 50, 'https://en.wikipedia.org/wiki/2010_Kraljevo_earthquake'),
  ('Q282940', '2010 Central European floods', 'The 2010 Central European floods were a devastating series of weather events which occurred across several Central European countries during May and June 2010. Poland was the worst affected.', 2010, 5, 14, 2010, 6, 9, 'day', '14 May 2010 – 9 June 2010', 50, 'https://en.wikipedia.org/wiki/2010_Central_European_floods'),
  ('Q4882657', 'Belgrade anti-gay riot', 'The Belgrade anti-gay riot was an incident of violence against LGBTQ people that occurred on 10 October 2010 during a pride parade, organized to promote LGBTQ rights in Serbia. The gay pride parade has been the first in Belgrade since 2001; a planned parade in 2009 was cancelled due to the threat of violence.', 2010, 10, 10, NULL, NULL, NULL, 'day', '10 October 2010', 47, 'https://en.wikipedia.org/wiki/Belgrade_anti-gay_riot'),
  ('Q10786861', 'Velika Ivanča shooting', 'A spree shooting occurred in the Serbian village of Velika Ivanča in the early hours of 9 April 2013. That morning, 60-year-old Ljubiša Bogdanović, fatally shot thirteen people across several different locations before attempting suicide.', 2013, 4, 9, NULL, NULL, NULL, 'day', '9 April 2013', 51, 'https://en.wikipedia.org/wiki/Velika_Ivan%C4%8Da_shooting'),
  ('Q16879871', '2014 Southeast Europe floods', 'Between 13 and 18 May 2014 a low-pressure cyclone designated Tamara and Yvette affected a large area of Southeastern and Central Europe, causing floods and landslides. Serbia and Bosnia and Herzegovina suffered the greatest damage, as the rain was the heaviest in 120 years of recorded weather measurements.', 2014, 5, 27, 2014, 5, 27, 'day', '27 May 2014', 63, 'https://en.wikipedia.org/wiki/2014_Southeast_Europe_floods'),
  ('Q63078193', 'Regional Roaming Agreement', 'The Regional Roaming Agreement, formally the Agreement on the price reduction of the roaming services in public mobile communications networks in the Western Balkans region, regulates the imposition of roaming charges within the countries in the Western Balkans; Albania, Kosovo, Bosnia and Herzegovina, North Macedonia, Montenegro and Serbia. The agreement covers both the charges mobile network operators can impose on their subscribers for using telephone and data services outside of the network''s member state, and the wholesale rates networks can charge each other to allow their subscribers…', 2019, 4, 4, NULL, NULL, NULL, 'day', '4 April 2019', 41, 'https://en.wikipedia.org/wiki/Regional_Roaming_Agreement'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q118152086', 'Mladenovac and Smederevo shootings', 'On the evening of 4 May 2023, a shooting spree occurred in the villages of Dubona and Malo Orašje, between Mladenovac and Smederevo, Serbia. Armed with an automatic assault rifle, the shooter opened fire from a car, resulting in the deaths of nine individuals, including an off-duty police officer, and leaving thirteen others injured.', 2023, 5, 4, NULL, NULL, NULL, 'day', '4 May 2023', 52, 'https://en.wikipedia.org/wiki/Mladenovac_and_Smederevo_shootings'),
  ('Q131554983', '2024–present Serbian anti-corruption protests', 'Mass protests took place in Serbia from November 2024 to October 2026. They began in Novi Sad after the canopy of the city''s railway station collapsed on 1 November 2024, killing 16 people and severely injuring one.', 2024, 11, 3, NULL, NULL, NULL, 'day', '3 November 2024', 63, 'https://en.wikipedia.org/wiki/2024%E2%80%932026_Serbian_anti-corruption_protests');
